# 132: Frailty assessment & clinical implications
kps += [
  {"id":"frailty-assessment-clinical-implications-d1","topic":"Frailty assessment & clinical implications","domain":"General internal medicine, preventive care & geriatrics","discipline":"medicine","stem":"An 80-year-old patient scores 3 on a validated frailty instrument preoperatively. What does frailty predict independent of age?","answer":"Higher morbidity and mortality; frailty predicts surgical outcomes more strongly than chronological age alone.","rationale":"Multiple studies show increasing frailty score correlates with higher morbidity and mortality, an association stronger than age alone.","bloom":"apply","source":[{"book":"Miller/Baby Miller","page":677}],"confusable_with":"disability (fixed deficit vs dynamic vulnerability)"},
  {"id":"frailty-assessment-clinical-implications-d2","topic":"Frailty assessment & clinical implications","domain":"General internal medicine, preventive care & geriatrics","discipline":"medicine","stem":"What five domains comprise the Fried frailty phenotype operational definition used perioperatively?","answer":"Weight loss, exhaustion, low activity, slow gait speed, and weak grip strength; >=3 of 5 = frail.","rationale":"The Fried criteria operationalize frailty as a biological syndrome of decreased reserve across these five domains.","bloom":"recall","source":[{"book":"Morgan & Mikhail","page":1494}],"confusable_with":"sarcopenia (muscle loss only, not full frailty phenotype)"},
  {"id":"frailty-assessment-clinical-implications-d3","topic":"Frailty assessment & clinical implications","domain":"General internal medicine, preventive care & geriatrics","discipline":"medicine","stem":"Which opioids should be avoided in frail older patients with impaired renal clearance and why?","answer":"Avoid meperidine (anticholinergic, normeperidine accumulation causes delirium) and morphine (morphine-6-glucuronide accumulates); fentanyl is preferred.","rationale":"Renally cleared active metabolites of meperidine and morphine accumulate in renal impairment, causing delirium and respiratory depression.","bloom":"apply","source":[{"book":"Miller/Baby Miller","page":675}],"confusable_with":"hydromorphone (also has active metabolite but less delirium risk than meperidine)"},
  {"id":"frailty-assessment-clinical-implications-d4","topic":"Frailty assessment & clinical implications","domain":"General internal medicine, preventive care & geriatrics","discipline":"medicine","stem":"What is the Comprehensive Geriatric Assessment (CGA) and who should conduct it?","answer":"The CGA systematically identifies medical and psychosocial factors causing functional limitations; it should be conducted by an interprofessional team.","rationale":"Frailty and functional limitations arise from interacting medical, psychological, and social factors best captured by team-based systematic evaluation.","bloom":"recall","source":[{"book":"MGH Housestaff Manual","page":170}],"confusable_with":"standard medical history and physical (does not capture psychosocial or functional domains)"},
  {"id":"frailty-assessment-clinical-implications-d5","topic":"Frailty assessment & clinical implications","domain":"General internal medicine, preventive care & geriatrics","discipline":"medicine","stem":"In a patient with advanced illness and increasing frailty, when should a serious illness conversation be initiated?","answer":"Early in the disease course -- especially with new progression, increasing hospitalizations, or intolerance of guideline-directed therapies.","rationale":"Early goals-of-care conversations align care with patient values before crisis, improving outcomes and reducing unwanted interventions.","bloom":"apply","source":[{"book":"MGH Housestaff Manual","page":166}],"confusable_with":"waiting until the patient is critically ill (too late for meaningful shared decision-making)"},
  {"id":"frailty-assessment-clinical-implications-d6","topic":"Frailty assessment & clinical implications","domain":"General internal medicine, preventive care & geriatrics","discipline":"medicine","stem":"A frail patient with AF requires anticoagulation. How should frailty influence the stroke prevention decision?","answer":"Frailty does not automatically preclude anticoagulation; stroke risk should inform therapy selection regardless of AF pattern, balanced against bleeding risk and patient preference.","rationale":"ACC/AHA 2023 AF guidelines emphasize individualized shared decision-making weighing stroke vs bleeding risk, not automatic exclusion of frail patients.","bloom":"analyze","source":[{"book":"Society Guideline: Guideline   ACC AHA 2023 Atrial Fibrillation","page":32}],"confusable_with":"automatically withholding anticoagulation from all frail patients"},
  {"id":"frailty-assessment-clinical-implications-d7","topic":"Frailty assessment & clinical implications","domain":"General internal medicine, preventive care & geriatrics","discipline":"medicine","stem":"The Mini-Cog cognitive screen used in geriatric frailty assessment consists of which two components?","answer":"3-item recall and clock drawing; score of 0 or 1-2 with abnormal clock draw suggests cognitive impairment.","rationale":"The Mini-Cog is a brief validated tool combining recall and executive function (clock draw) to screen for cognitive impairment in perioperative/frailty assessment.","bloom":"recall","source":[{"book":"Morgan & Mikhail","page":1494}],"confusable_with":"MMSE (longer 30-item cognitive screen)"}
]

kps.append({"_type":"illness_script","topic":"Frailty assessment & clinical implications","discipline":"medicine","enabling_conditions":"Advanced age, multimorbidity, malnutrition, physical inactivity, prior hospitalization","pathophysiology":"Dysregulated energy homeostasis, sarcopenia, inflammation, and neuroendocrine dysregulation reduce physiologic reserve across organ systems","time_course":"Accumulates over years; acute illness or surgery can precipitate rapid decompensation","key_features":"Weight loss, exhaustion, low physical activity, slow gait, weak grip; >=3/5 Fried criteria = frail","consequence_if_missed":"Underestimation of surgical/procedural risk, inadequate consent, failure to initiate goals-of-care discussions"})

# 133: Functional decline, mobility & rehabilitation
kps += [
  {"id":"functional-decline-mobility-rehab-d1","topic":"Functional decline, mobility & rehabilitation in hospitalized older adults","domain":"General internal medicine, preventive care & geriatrics","discipline":"medicine","stem":"What are the major risk factors for needing post-acute care after hospitalization?","answer":"Living alone, impaired mobility, depression, and significant comorbidity predict post-acute care utilization.","rationale":"These factors impair the patient's ability to manage self-care safely at home after hospital discharge.","bloom":"recall","source":[{"book":"MGH Housestaff Manual","page":271}],"confusable_with":"severity of acute illness alone (social and functional factors are equally important determinants)"},
  {"id":"functional-decline-mobility-rehab-d2","topic":"Functional decline, mobility & rehabilitation in hospitalized older adults","domain":"General internal medicine, preventive care & geriatrics","discipline":"medicine","stem":"Why are skilled nursing facilities not appropriate for patients requiring rapid diagnostics or significant acute management?","answer":"SNFs lack capability for rapid diagnostics (CT), invasive procedures, or acute management of hypoxemia or hypotension.","rationale":"Post-acute care settings are designed for rehabilitation and skilled nursing, not acute diagnostic workup or hemodynamic management.","bloom":"apply","source":[{"book":"MGH Housestaff Manual","page":271}],"confusable_with":"step-down units (have intermediate monitoring capability)"},
  {"id":"functional-decline-mobility-rehab-d3","topic":"Functional decline, mobility & rehabilitation in hospitalized older adults","domain":"General internal medicine, preventive care & geriatrics","discipline":"medicine","stem":"In hospitalized patients with heart failure, what does exercise training meta-analysis suggest about cardiovascular outcomes?","answer":"Exercise training is associated with modest reductions in cardiovascular mortality and HF hospitalizations after prespecified adjustment, though primary analyses may not always reach significance.","rationale":"HF-ACTION and meta-analyses show exercise training improves functional capacity with a trend toward reduced cardiovascular events.","bloom":"analyze","source":[{"book":"Society Guideline: Guideline   ACC AHA 2022 Heart Failure","page":39}],"confusable_with":"bed rest (historically prescribed but worsens deconditioning and outcomes in HF)"},
  {"id":"functional-decline-mobility-rehab-d4","topic":"Functional decline, mobility & rehabilitation in hospitalized older adults","domain":"General internal medicine, preventive care & geriatrics","discipline":"medicine","stem":"What is the major clinical risk of failing to differentiate delirium from dementia in a hospitalized older adult?","answer":"Underdiagnosis of delirium-superimposed-on-dementia (DSD), associated with $38-152 billion annual costs and worse outcomes; missed in up to 78-89% of cases.","rationale":"DSD is underdiagnosed because behavioral changes are attributed to baseline dementia, delaying treatment of a potentially reversible acute condition.","bloom":"analyze","source":[{"book":"StatPearls: StatPearls   Delirium  Diagnosis, Subtypes & Assessment","page":8}],"confusable_with":"worsening dementia (chronic, not acute; delirium always requires acute workup)"},
  {"id":"functional-decline-mobility-rehab-d5","topic":"Functional decline, mobility & rehabilitation in hospitalized older adults","domain":"General internal medicine, preventive care & geriatrics","discipline":"medicine","stem":"Which interprofessional team members are key to addressing post-hospitalization functional decline?","answer":"Case management, physical therapy (PT), and occupational therapy (OT) are primary; SNF or home health arranged based on assessed functional needs.","rationale":"Coordinated discharge planning addressing mobility, ADLs, and social support reduces readmission risk and promotes functional recovery.","bloom":"apply","source":[{"book":"MGH Housestaff Manual","page":271}],"confusable_with":"physician discharge planning alone (insufficient without PT/OT/case management input)"},
  {"id":"functional-decline-mobility-rehab-d6","topic":"Functional decline, mobility & rehabilitation in hospitalized older adults","domain":"General internal medicine, preventive care & geriatrics","discipline":"medicine","stem":"Frailty at time of ambulatory surgery is best assessed using what approach?","answer":"Frailty is best viewed as an overall risk assessment based on age and disease-related factors across multiple organ systems, not a single variable; the ACS NSQIP frailty index is one validated tool.","rationale":"Multivariate frailty scoring captures the cumulative physiologic deficit burden better than single-domain measures for perioperative risk stratification.","bloom":"apply","source":[{"book":"Miller/Baby Miller","page":677}],"confusable_with":"ASA physical status alone (does not capture frailty dimensions beyond comorbidity)"}
]

# 134: Gestational Diabetes
kps += [
  {"id":"gestational-diabetes-d1","topic":"Gestational Diabetes & Diabetes in Pregnancy","domain":"Internal medicine: endocrinology","discipline":"medicine","stem":"Which pregnancy complication is strongly associated with maternal obesity (BMI >=30)?","answer":"Gestational diabetes mellitus, as well as gestational hypertension, preeclampsia, and delivery of large-for-gestational-age infants.","rationale":"Obesity promotes insulin resistance and metabolic dysregulation, increasing risk for gestational diabetes and hypertensive disorders.","bloom":"recall","source":[{"book":"Morgan & Mikhail","page":1387}],"confusable_with":"pre-existing type 2 diabetes (gestational DM is newly diagnosed in pregnancy)"},
  {"id":"gestational-diabetes-d2","topic":"Gestational Diabetes & Diabetes in Pregnancy","domain":"Internal medicine: endocrinology","discipline":"medicine","stem":"When should ADA diabetes screening begin in an asymptomatic adult, and how does prior gestational DM modify the interval?","answer":"Begin at age >=35 every 3 years; history of gestational DM with BMI >=25 plus risk factors warrants screening at any age, repeating annually if pre-diabetes is detected.","rationale":"Gestational DM reflects underlying insulin resistance predisposing to future T2DM; earlier and more frequent screening is warranted.","bloom":"apply","source":[{"book":"MGH Housestaff Manual","page":181}],"confusable_with":"screening only from age 35 (history of GDM triggers earlier screening)"},
  {"id":"gestational-diabetes-d3","topic":"Gestational Diabetes & Diabetes in Pregnancy","domain":"Internal medicine: endocrinology","discipline":"medicine","stem":"How is glucose control best monitored longitudinally in diabetic patients, and what end-organ complication do the diagnostic glycemic thresholds reflect?","answer":"HbA1c monitors long-term glucose control; the diagnostic criteria thresholds reflect the level of glycemia at which retinopathy risk begins.","rationale":"Each diagnostic criterion for diabetes mirrors the glycemic level at which microvascular retinal damage begins.","bloom":"recall","source":[{"book":"Miller/Baby Miller","page":546}],"confusable_with":"fasting glucose alone (HbA1c captures 3-month average and is more stable for monitoring)"},
  {"id":"gestational-diabetes-d4","topic":"Gestational Diabetes & Diabetes in Pregnancy","domain":"Internal medicine: endocrinology","discipline":"medicine","stem":"What is gestational AVP disorder, when does it present, and what distinguishes it from central DI?","answer":"Gestational AVP-D (~1:30,000 pregnancies) results from placental vasopressinase degrading AVP; presents third trimester, resolves 2-3 weeks postpartum; unlike central DI, it is transient and responds to desmopressin but not to AVP.","rationale":"Vasopressinase levels are up to 300-fold higher in pregnancy; this enzyme degrades endogenous AVP, causing a transient DI-like state that is unique to pregnancy.","bloom":"analyze","source":[{"book":"StatPearls: StatPearls   Diabetes Insipidus (DI)","page":9}],"confusable_with":"central DI (permanent, not self-resolving postpartum; responds to both AVP and desmopressin)"},
  {"id":"gestational-diabetes-d5","topic":"Gestational Diabetes & Diabetes in Pregnancy","domain":"Internal medicine: endocrinology","discipline":"medicine","stem":"What are the classic symptoms of hyperglycemia supporting a clinical diabetes diagnosis?","answer":"Polyuria, polydipsia, weight loss, and blurred vision.","rationale":"Classic hyperglycemia symptoms reflect osmotic diuresis, compensatory thirst, catabolism, and osmotic lens changes from elevated glucose.","bloom":"recall","source":[{"book":"Miller/Baby Miller","page":546}],"confusable_with":"DKA symptoms (also include nausea, vomiting, Kussmaul respirations beyond the classic triad)"},
  {"id":"gestational-diabetes-d6","topic":"Gestational Diabetes & Diabetes in Pregnancy","domain":"Internal medicine: endocrinology","discipline":"medicine","stem":"Multiple gestation pregnancy carries what increased metabolic complication risk?","answer":"Increased risk of gestational diabetes (and preterm labor, hypertensive disorders, hyperemesis gravidarum, anemia, and IUGR).","rationale":"Twin and higher-order pregnancies amplify placental anti-insulin hormonal effects, raising gestational DM risk further beyond singleton pregnancy.","bloom":"recall","source":[{"book":"Miller/Baby Miller","page":619}],"confusable_with":"pre-existing T2DM (gestational DM is newly diagnosed during this pregnancy)"}
]

kps.append({"_type":"illness_script","topic":"Gestational Diabetes & Diabetes in Pregnancy","discipline":"medicine","enabling_conditions":"Obesity BMI>=30, prior GDM, family history T2DM, multiple gestation, PCOS, advanced maternal age","pathophysiology":"Placental hormones (hPL, cortisol, progesterone) induce progressive insulin resistance; beta cell compensation fails leading to maternal hyperglycemia","time_course":"Develops 2nd-3rd trimester as placental bulk and insulin resistance peak; resolves postpartum but 50% progress to T2DM within 10 years","key_features":"Asymptomatic hyperglycemia on GCT screen; large-for-gestational-age fetus; neonatal hypoglycemia; macrosomia risk","consequence_if_missed":"Macrosomia, shoulder dystocia, neonatal hypoglycemia, increased cesarean delivery rate, long-term maternal T2DM"})

# 135: HFpEF
kps += [
  {"id":"hfpef-d1","topic":"Heart Failure with Preserved Ejection Fraction (HFpEF)","domain":"Internal medicine: cardiology","discipline":"medicine","stem":"Which drug class has the most consistent evidence of reducing HF hospitalization in HFpEF, supported by EMPEROR-Preserved and DELIVER trials?","answer":"SGLT2 inhibitors (empagliflozin, dapagliflozin) reduce HF hospitalizations in HFpEF and are now guideline-indicated.","rationale":"SGLT2 inhibitor trials demonstrated significant reductions in worsening HF events in patients with EF >40-45%, the first class with robust benefit in HFpEF.","bloom":"apply","source":[{"book":"StatPearls","page":12}],"confusable_with":"ACE inhibitors (modest benefit in HFpEF compared with robust HFrEF data)"},
  {"id":"hfpef-d2","topic":"Heart Failure with Preserved Ejection Fraction (HFpEF)","domain":"Internal medicine: cardiology","discipline":"medicine","stem":"What did TOPCAT show regarding spironolactone in symptomatic HF with LVEF >45%?","answer":"TOPCAT showed borderline reduction in HF hospitalizations with spironolactone (not statistically significant overall); benefit was strongest in the Americas subgroup.","rationale":"Mineralocorticoid receptor antagonists reduce myocardial fibrosis; TOPCAT's mixed results reflect HFpEF heterogeneity.","bloom":"analyze","source":[{"book":"StatPearls","page":12}],"confusable_with":"eplerenone in HFrEF (EMPHASIS-HF showed clear mortality benefit in reduced EF)"},
  {"id":"hfpef-d3","topic":"Heart Failure with Preserved Ejection Fraction (HFpEF)","domain":"Internal medicine: cardiology","discipline":"medicine","stem":"What is the optimal blood pressure target and antihypertensive regimen in HFpEF?","answer":"Optimal BP target in HFpEF is not precisely defined; RAAS antagonists (ACEi, ARB, MRA, possibly ARNi) are reasonable first-line agents given their use in HFpEF trials, though evidence is extrapolated from general hypertension guidelines.","rationale":"Hypertension drives LV hypertrophy and diastolic dysfunction in HFpEF; RAAS blockade addresses the underlying substrate.","bloom":"analyze","source":[{"book":"Society Guideline: Guideline   ACC AHA 2022 Heart Failure","page":67}],"confusable_with":"applying HFrEF mortality-benefit data directly to HFpEF management"},
  {"id":"hfpef-d4","topic":"Heart Failure with Preserved Ejection Fraction (HFpEF)","domain":"Internal medicine: cardiology","discipline":"medicine","stem":"What role does BNP measurement play in differentiating HFpEF from other causes of dyspnea?","answer":"Elevated BNP/NT-proBNP supports a cardiac cause of dyspnea; BNP is released from the heart in response to impaired ventricular function and volume or pressure overload.","rationale":"BNP reflects ventricular wall stress; elevated levels indicate impaired function whether EF is reduced or preserved.","bloom":"apply","source":[{"book":"Morgan & Mikhail","page":659}],"confusable_with":"normal BNP ruling out HFpEF (HFpEF with obesity can have lower BNP relative to degree of dysfunction)"},
  {"id":"hfpef-d5","topic":"Heart Failure with Preserved Ejection Fraction (HFpEF)","domain":"Internal medicine: cardiology","discipline":"medicine","stem":"In a patient with new HFrEF and new AF, what possibility should be investigated before attributing the EF reduction to cardiomyopathy?","answer":"Arrhythmia-induced cardiomyopathy should be suspected; an aggressive rhythm control approach should be considered, as EF may recover with restoration of sinus rhythm.","rationale":"AF-induced tachycardia-mediated cardiomyopathy is reversible with rhythm control; missing this alters prognosis and management.","bloom":"analyze","source":[{"book":"Society Guideline: Guideline   ACC AHA 2023 Atrial Fibrillation","page":92}],"confusable_with":"permanent rate control strategy (may miss reversible tachycardia-mediated cardiomyopathy)"},
  {"id":"hfpef-d6","topic":"Heart Failure with Preserved Ejection Fraction (HFpEF)","domain":"Internal medicine: cardiology","discipline":"medicine","stem":"What defines HF with improved EF (HFimpEF) and why is medication continuation recommended?","answer":"HFimpEF = previously reduced EF that has improved to >=40%; TRED-HF showed medication withdrawal caused relapse, so GDMT should continue despite improved EF.","rationale":"EF improvement may represent reverse remodeling dependent on ongoing medication, not a permanent cure; stopping treatment risks relapse.","bloom":"analyze","source":[{"book":"Society Guideline: Guideline   ACC AHA 2022 Heart Failure","page":131}],"confusable_with":"HFpEF (always-preserved EF without prior reduction)"},
  {"id":"hfpef-d7","topic":"Heart Failure with Preserved Ejection Fraction (HFpEF)","domain":"Internal medicine: cardiology","discipline":"medicine","stem":"NYHA Class IV heart failure is defined how, and what is its clinical implication for device therapy?","answer":"NYHA IV = symptoms at rest or with any activity; it is an indication to consider advanced therapies including CRT if criteria met, though GDMT optimization precedes device decisions.","rationale":"NYHA functional class is an independent predictor of mortality and determines eligibility for device implantation (ICD/CRT criteria require specified NYHA class).","bloom":"apply","source":[{"book":"StatPearls","page":3}],"confusable_with":"ACC/AHA Stage D (based on structural disease and refractory symptoms, not just NYHA class)"}
]

kps.append({"_type":"illness_script","topic":"Heart Failure with Preserved Ejection Fraction (HFpEF)","discipline":"medicine","enabling_conditions":"Hypertension, obesity, diabetes, older age, female sex, atrial fibrillation","pathophysiology":"LV hypertrophy and fibrosis cause impaired diastolic relaxation and elevated filling pressures with preserved EF (>=50%); exercise intolerance from inability to augment stroke volume","time_course":"Chronic progressive; decompensation triggered by hypertension, AF, dietary indiscretion, or infection","key_features":"Exertional dyspnea, elevated BNP, pulmonary congestion, LVEF >=50% on echo, diastolic dysfunction grade >=2","consequence_if_missed":"Attributed to pulmonary or non-cardiac cause; failure to address underlying hypertension or AF driving the syndrome; withholding SGLT2 inhibitor benefit"})

print(json.dumps(kps, ensure_ascii=False, indent=2))
